def cause_is_value_error():
    try:
        load_int("x")
    except LoadError as error:
        return isinstance(error.__cause__, ValueError)
    return False

check("load_int('42') == 42", lambda: load_int("42"), 42)
check("load_int('x') keeps ValueError as the cause", cause_is_value_error, True)
check('negative', lambda: load_int('-9'), -9)
check('zero', lambda: load_int('0'), 0)
check('whitespace', lambda: load_int(' 7 '), 7)
check('decimal rejected', lambda: raises(lambda: load_int('1.2'), LoadError), True)
check('empty rejected', lambda: raises(lambda: load_int(''), LoadError), True)
